import {escapeHtml as esc} from './agent-view.js';
import {ROLES} from './agents.js';
import {LIVE_STATUSES} from './runtime-client.js';
import {runProgressView} from './progress-view.js';
const time=value=>value?new Date(value).toLocaleString('zh-TW',{hour12:false}):'—';
export function liveBadge(runtime,agent){return `<span class="live-status ${runtime.error?'stale':agent.status}">${runtime.error?'狀態過期':LIVE_STATUSES[agent.status]}</span>`;}
export function runtimeView(runtime){
  const r=runtime.data?.latestRun,active=r&&['queued','running'].includes(r.status),alive=r?.agents.filter(a=>a.processAlive===true).length||0;
  return `<div class="page-heading"><div><p class="eyebrow">LOCAL EXECUTION · POLLING</p><h1>代理人執行監控</h1><p>讀取本機服務的行程狀態、工作輸出與執行紀錄。</p></div><div class="actions"><button class="button secondary" data-live-refresh>↻ 立即更新</button><button class="button primary" data-live-run ${runtime.error||!runtime.capabilities||active?'disabled':''}>▷ 執行專案檢查</button>${active?`<button class="button danger" data-live-cancel="${esc(r.id)}">取消執行</button>`:''}</div></div><section class="card polling-bar"><div><strong>${runtime.error?'服務未連線／快照過期':runtime.lastSuccess?'本機執行服務已連線':'正在確認執行服務'}</strong><p>最近成功更新：${time(runtime.lastSuccess)} · 已 polling ${runtime.pollCount} 次${runtime.busy?' · 更新中':''}</p></div><label>更新間隔<select data-live-interval>${[1000,2000,5000,10000].map(ms=>`<option value="${ms}" ${runtime.interval===ms?'selected':''}>${ms/1000} 秒</option>`).join('')}</select></label><button class="button secondary" data-live-toggle>${runtime.enabled?'暫停 polling':'繼續 polling'}</button></section>${runtime.error?`<div class="error-banner spaced">${esc(runtime.error)}。自動重試${runtime.enabled?'中':'已暫停'}；過期快照不代表行程仍在執行。請在 WSL 執行 <code>bash scripts/start-gui.sh</code> 並開啟 <code>http://localhost:8765</code>（或你的指定連接埠）。</div>`:''}<div class="demo-banner spaced"><span class="info-icon">i</span><div><strong>本機代理人行程 · 實際執行</strong><span>專案檢查會執行測試；技能實驗會搜尋規則並評估候選。LLM 技能實驗會呼叫已儲存的模型服務 並產生候選；Python 修復實驗接入 nanobot SDK；GEPA 技能最佳化沿用 nanobot runner。版本皆需人工核准。</span></div></div><div class="metrics">${metric('本次角色',r?.agents.length||0,'每個角色對應一個受監督的行程')}${metric('執行中行程',runtime.error?'未知':alive,'根據最近快照的 subprocess 存活檢查')}${metric('流程狀態',r?(runtime.error?'過期':LIVE_STATUSES[r.status]):'尚未開始',r?.checksPassed===false?'流程結束，但測試未通過':r?.id||'按「執行專案檢查」開始')}${metric('Polling 間隔',`${runtime.interval/1000} 秒`,runtime.enabled?'持續 polling，請求完成後安排下一次':'目前暫停更新，後端工作不會停止')}</div>${runProgressView(runtime,r)}${r?`<div class="live-agent-grid">${r.agents.map(a=>`<section class="card live-agent"><div class="card-heading"><div><p class="eyebrow">${ROLES[a.role]||esc(a.role)}</p><h2>${esc(a.name)}</h2><p>${esc(a.id)} · ${esc(a.adapter||'native-tool-agent')}</p></div>${liveBadge(runtime,a)}</div><div class="live-agent-body"><p class="live-task">${esc(a.task)}</p><dl class="agent-properties"><dt>PID</dt><dd>${a.pid??'—'}${runtime.error?' · 目前未確認':a.processAlive===true?' · 存活':a.processAlive===null?' · 未確認':a.pid?' · 已結束':''}</dd><dt>開始</dt><dd>${time(a.startedAt)}</dd><dt>結束</dt><dd>${time(a.endedAt)}</dd><dt>最近檢查</dt><dd>${time(a.updatedAt)}</dd><dt>Exit code</dt><dd>${a.exitCode??'—'}</dd></dl>${a.error?`<p class="form-error">${esc(a.error)}</p>`:''}<pre class="live-output">${esc(a.logTail||'尚無行程輸出')}</pre></div></section>`).join('')}</div><section class="card spaced"><div class="card-heading"><div><h2>實際工作紀錄</h2><p>${esc(r.id)} · ${r.task==='gepa-evolution'?'GEPA 技能最佳化':r.task==='nanobot-repair'?'nanobot Python 修復':r.task==='llm-evolution'?'LLM 技能演化':r.task==='skill-evolution'?'規則技能演化':'專案檢查'} · 建立於 ${time(r.createdAt)} · 最近服務更新 ${time(r.updatedAt)}</p></div></div><ol class="live-event-list">${r.events.slice().reverse().map(e=>`<li><time>${time(e.at)}</time><code>${esc(e.agentId||'SUPERVISOR')}</code><span>${esc(e.text)}</span></li>`).join('')}</ol></section><section class="card spaced"><div class="card-heading"><div><h2>執行產物</h2><p>保存在專案 .local/runs/ 下；不會寫入 Git。</p></div></div><div class="artifact-links">${r.artifacts.map(name=>`<a href="/api/v1/runtime/runs/${encodeURIComponent(r.id)}/artifacts/${encodeURIComponent(name)}" target="_blank" rel="noreferrer">${esc(name)} ↗</a>`).join('')||'<p class="muted">執行結束後列出產物；目前輸出可在上方檢閱。</p>'}</div></section>`:'<section class="card"><div class="empty">尚無實際工作紀錄。啟動後會使用目前啟用的五個角色設定，依序執行固定的專案檢查流程。<br>流程執行期間不接受第二個工作；關閉頁面不會取消後端工作。</div></section>'}<section class="card spaced"><div class="card-heading"><h2>近期流程</h2></div><div class="table-wrap"><table><thead><tr><th>執行 ID</th><th>狀態</th><th>建立時間</th></tr></thead><tbody>${(runtime.data?.runs||[]).map(v=>`<tr><td><code>${esc(v.id)}</code></td><td>${LIVE_STATUSES[v.status]||esc(v.status)}</td><td>${time(v.createdAt)}</td></tr>`).join('')||'<tr><td colspan="3">尚無紀錄</td></tr>'}</tbody></table></div></section>`;
}
function metric(label,value,caption){return `<article class="metric"><div>${label}</div><strong class="runtime-metric">${esc(value)}</strong><small>${esc(caption)}</small></article>`;}
